SELECT '按状态统计:' AS info;
SELECT status, COUNT(*) AS count,
    CASE status 
        WHEN 3 THEN '审核通过' 
        WHEN 4 THEN '已归档'
    END AS status_name
FROM enterprise_report_info
GROUP BY status;

